Algoritmo UnoADiez
  Definir n Como Entero;
  Repetir
    Leer n;
  Hasta Que n >= 1 Y n <= 10
  Escribir "Aceptado: ", n;
FinAlgoritmo

Algoritmo Maxima
  Definir temperatura Como Entero;
  Definir maxima Como Entero;
  Leer maxima;
  Para i <- 2 Hasta 5 Hacer
    Leer temperatura;
    Si temperatura > maxima Entonces
      maxima <- temperatura;
    FinSi
  FinPara
  Escribir "Máxima: ", maxima;
FinAlgoritmo

Algoritmo Primo
  Definir n Como Entero;
  Leer n;
  Definir esPrimo Como Logico <- n >= 2;
  Para d <- 2 Hasta n - 1 Hacer
    Si n mod d = 0 Entonces
      esPrimo <- Falso;
      Salir;
    FinSi
  FinPara
  Si esPrimo Entonces
    Escribir "Es primo";
  Sino
    Escribir "No es primo";
  FinSi
FinAlgoritmo
